    try {
      const [ { data: g }, { data: s }, { data: m_orders }, { data: o }, { data: i }, { data: c }, { data: m }, { data: ms }, { data: r }, { data: p }, { data: cr } ] = await Promise.all([
        supabase.from('commandes_gros').select('*'),
        supabase.from('commandes_siteweb').select('*'),
        supabase.from('commandes_merch').select('*'),
        supabase.from('offres').select('*'),
        supabase.from('inventory').select('*'),
        supabase.from('charges').select('*'),
        supabase.from('client_comptoir').select('*'), // Isolation: dedicated table
        supabase.from('marketing_spends').select('*'),
        supabase.from('commandes_retours').select('*'),
        supabase.from('payouts').select('*'),
        supabase.from('credits').select('*')
      ]);
      if (g) setGros(g); 
      if (s) setSiteweb(s); 
      if (m_orders) setMerch(m_orders);
      if (o) setOffres(o); 
      if (i) setInventory(i); 
      if (c) setCharges(c); 
      if (m) setClientComptoir(m); 
      if (ms) setMarketingSpends(ms);
      if (r) setRetours(r);
      if (p) setPayouts(p);
      if (cr) setCredits(cr);
      setLastSynced(new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }));
    } catch (e) { 
      console.error("Supabase fetch error:", e); 
    } finally { 
      if (!isSilent) setIsSyncing(false); 
      setIsInitialLoaded(true);
    }
  }, []);

  useEffect(() => {
    fetchAllData();
    if (!supabase) return;
    const tables = ['commandes_gros', 'commandes_siteweb', 'commandes_merch', 'offres', 'inventory', 'charges', 'client_comptoir', 'marketing_spends', 'commandes_retours', 'payouts', 'credits'];
    const channel = supabase.channel('merchdz_realtime');
    tables.forEach(table => {
      channel.on('postgres_changes', { event: '*', schema: 'public', table }, (payload) => {
        if (realtimeTimeoutRef.current) clearTimeout(realtimeTimeoutRef.current);
        realtimeTimeoutRef.current = setTimeout(() => { fetchAllData(true); }, 750);
      });
    });
    channel.subscribe();
    return () => {
      if (realtimeTimeoutRef.current) clearTimeout(realtimeTimeoutRef.current);
      supabase.removeChannel(channel);
    };
  }, [fetchAllData]);

  const login = useCallback(async (password: string) => {
